import{_ as t,o as r,c as e,a2 as s}from"./chunks/framework.DuPBmefI.js";const u=JSON.parse('{"title":"协恩中学 · 年份未注明 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-fd1436e9","school_zh":"协恩中学","school_en":"—","grade":"s1","year":"unknown","year_label":"年份未注明","type":"interview","title":"协恩中学 · 年份未注明 · 中一 · 面试","anonymous":true,"source_ids":["C1821-HYS-U","HOT22-HYS","HYS-S1-GUIDE-DETAIL"],"rounds":["unknown","r1","r2"]},"headers":[],"relativePath":"reports/school-fd1436e9/s1/unknown-interview.md","filePath":"reports/school-fd1436e9/s1/unknown-interview.md"}'),n={name:"reports/school-fd1436e9/s1/unknown-interview.md"};function p(a,o,l,c,g,d){return r(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="协恩中学-·-年份未注明-·-中一-·-面试" tabindex="-1">协恩中学 · 年份未注明 · 中一 · 面试 <a class="header-anchor" href="#协恩中学-·-年份未注明-·-中一-·-面试" aria-label="Permalink to &quot;协恩中学 · 年份未注明 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-fd1436e9">← 返回协恩中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c1821-hys-u" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-c1821-hys-u" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-c1821-hys-u}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>英语：</strong> 英语</p><p><strong>比较选择短讲</strong></p><p>比较电子书与纸本书、电子练习与纸笔练习，并说明选择理由；部分题目提供词语。另有卡通片与纪录片二选一的短讲。纸本与电子课本比较题限时1分钟。</p></blockquote><blockquote><p><strong>语文：</strong> 中文（口语未注明）</p><p><strong>文言文与剧本理解</strong></p><p>文言文理解含选择题；一题涉及对李白前后态度的变化，要求复述内容并作选择。另有父子书法故事，以及两人争论奖学金应授予哪类人的剧本，剧本后有3道选择题。</p><p><strong>双人讨论</strong></p><p>两名学生讨论政府是否应该照顾长者。</p></blockquote><blockquote><p><strong>数学：</strong> 中文、英语</p><p><strong>限时作答的不同版本</strong></p><p>有iPad题目，限时2分钟，不会可跳过；另有题本30题、限时3分钟的反馈，懂得答案时向老师口头作答，同样可跳题。</p></blockquote><h2 id="record-hot22-hys" tabindex="-1">资料来源：热门港校面试真题集：中学篇.pdf <a class="header-anchor" href="#record-hot22-hys" aria-label="Permalink to &quot;资料来源：热门港校面试真题集：中学篇.pdf {#record-hot22-hys}&quot;">​</a></h2><p><strong>资料类型：</strong> 2022/23机构汇编中的历史面试题</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>语文：</strong> 中文（口语未注明）</p><p><strong>阅读题量</strong></p><p>一篇文言文与一篇议论文，各回答5道问题。</p><p><strong>一分钟观点表达</strong></p><p>就论题表明立场并解释：学生应否带手机回校；应否按成绩分班；子女做家务应否获得报酬；应否让学生自行制定校规。</p></blockquote><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>平板快速运算</strong></p><p>3分钟内尽量完成iPad题目，涉及分数、小数的四则运算，以及百分比加减。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>图片比较与偏好</strong></p><p>准备一分钟、表达一分钟。比较摇滚演出与管弦乐演出、辩论与女童军、K-pop与古典音乐、卡通与纪录片、快餐店与自助餐；说明人们为何喜欢或参与，再表达自己的选择。</p><p><strong>课外活动</strong></p><p>说明参加课外活动的好处。</p></blockquote><blockquote><p><strong>小组讨论：</strong> 中文（口语未注明）</p><p><strong>文言人物与田园生活</strong></p><p>准备6分钟，各人先发言30秒，再讨论3分钟。题目包括文言文人物性格，以及香港人是否适合田园闲适生活。</p></blockquote><blockquote><p><strong>小组讨论：</strong> 英语</p><p><strong>疫情与学习</strong></p><p>疫情期间做了什么、学到什么、有何积极影响；如何联系同学和朋友。</p><p><strong>时间与校园</strong></p><p>如何管理时间、时间表是否有帮助；偏好网上学习还是面授；为何申请协恩。</p></blockquote><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>小组讨论：</strong> 中文（口语未注明）</p><p><strong>兴趣与升中期望</strong></p><p>喜欢做什么、平时如何学习英文、喜欢中文还是英文及原因；对中学生活有何期望、希望学到什么，以及还申请了哪些学校。</p></blockquote><h2 id="record-hys-s1-guide-detail" tabindex="-1">资料来源：香港学校面试题【协恩 英皇 真光 皇仁 圣保罗 英华】.docx <a class="header-anchor" href="#record-hys-s1-guide-detail" aria-label="Permalink to &quot;资料来源：香港学校面试题【协恩 英皇 真光 皇仁 圣保罗 英华】.docx {#record-hys-s1-guide-detail}&quot;">​</a></h2><p><strong>资料类型：</strong> 机构整理：历史面试题目</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准-1" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-1" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>语文：</strong> 中文</p><p><strong>朗读、词义与常识</strong></p><p>朗读文章并解释“瞻前顾后”，说明能否用“优柔寡断”替换；回答“仲春”是农历哪个月；用含动物的成语形容勇敢、不怕困难。</p></blockquote><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>图形重量</strong></p><p>2个三角形加3个圆的重量，等于1个三角形加4个圆。已知每个三角形重200克，求圆的重量。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>朗读答问</strong></p><p>朗读英文文章，再回答老师追问。</p></blockquote>',31)])])}const i=t(n,[["render",p]]);export{u as __pageData,i as default};
